CREATE TABLE IF NOT EXISTS profiles (id TEXT PRIMARY KEY NOT NULL, email TEXT NOT NULL UNIQUE, quota_remaining INTEGER DEFAULT 30 NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS boards (id TEXT PRIMARY KEY NOT NULL, owner_id TEXT NOT NULL, title TEXT NOT NULL, version INTEGER DEFAULT 1 NOT NULL, scene TEXT DEFAULT '{}' NOT NULL, updated_at TEXT DEFAULT CURRENT_TIMESTAMP NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS boards_owner_title_idx ON boards(owner_id, title);
CREATE TABLE IF NOT EXISTS assets (id TEXT PRIMARY KEY NOT NULL, owner_id TEXT NOT NULL, board_id TEXT NOT NULL, kind TEXT NOT NULL, title TEXT NOT NULL, source_url TEXT, object_key TEXT, extracted_text TEXT, metadata TEXT DEFAULT '{}' NOT NULL, status TEXT DEFAULT 'idle' NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE INDEX IF NOT EXISTS assets_owner_created_idx ON assets(owner_id, created_at);
CREATE TABLE IF NOT EXISTS relations (id TEXT PRIMARY KEY NOT NULL, board_id TEXT NOT NULL, source_id TEXT NOT NULL, target_id TEXT NOT NULL, type TEXT NOT NULL, origin TEXT NOT NULL, score REAL);
CREATE TABLE IF NOT EXISTS analyses (id TEXT PRIMARY KEY NOT NULL, asset_id TEXT NOT NULL, schema_version INTEGER DEFAULT 1 NOT NULL, provider TEXT NOT NULL, model TEXT NOT NULL, result TEXT, status TEXT NOT NULL, error TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY NOT NULL, owner_id TEXT NOT NULL, type TEXT NOT NULL, subject_id TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER DEFAULT 0 NOT NULL, result TEXT, error TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TEXT DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS share_links (id TEXT PRIMARY KEY NOT NULL, board_id TEXT NOT NULL, owner_id TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, revoked_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS usage_ledger (id TEXT PRIMARY KEY NOT NULL, owner_id TEXT NOT NULL, action TEXT NOT NULL, units INTEGER NOT NULL, job_id TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY NOT NULL, owner_id TEXT NOT NULL, name TEXT NOT NULL, payload TEXT DEFAULT '{}' NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP NOT NULL);

